{
  "verdict": "SCAM",
  "risk_score": 95,
  "confidence": "HIGH",
  "scam_type": "Delivery Scam",
  "injection_attempt_detected": false,
  "extracted_text": "Your parcel could not be delivered due to an incomplete address. Share the 6-digit OTP we just sent you with our agent to reschedule. Pay Rs 25 redelivery fee: bit.ly/3xYzPQ",
  "red_flags": [
    {
      "phrase": "Share the 6-digit OTP we just sent you with our agent",
      "tag": "OTP_REQUEST",
      "why": "Legitimate delivery agents never ask for your OTP over phone or chat."
    },
    {
      "phrase": "Pay Rs 25 redelivery fee",
      "tag": "PAYMENT_REQUEST",
      "why": "Scammers ask for small fees through unknown links to steal your card details."
    },
    {
      "phrase": "bit.ly/3xYzPQ",
      "tag": "SUSPICIOUS_LINK",
      "why": "Shortened links hide the real web address and are commonly used in fraud."
    }
  ],
  "explanation": "This message is a classic scam. Real delivery companies will never ask you to share your private OTP or pay a small fee through a random link to get your package. The link is hidden using a shortening service, which is a trick scammers use to hide dangerous websites.",
  "next_steps": [
    "Do not click the link or reply to the message.",
    "Never share your OTP, UPI PIN, or passwords with anyone.",
    "Block and report the sender on your phone.",
    "If you shared any financial details, call 1930 immediately and report it at cybercrime.gov.in."
  ],
  "share_message": "Beware of delivery messages asking you to share an OTP or pay a small fee through a link. It is a scam to steal your money and details. Never click or share anything."
}

